UPDATE public.he_dispatch d
SET amount = v.tally_amount,
    tds_amount = v.tally_tds
FROM v
WHERE d.flock_id = 'd07f7336-7e6f-4cdb-841d-059fea1643b2'::uuid
  AND d.dc_no = v.dc_no;

SELECT count(*)::int AS n_updated FROM public.he_dispatch d
JOIN (VALUES (3432),(3433),(3435),(3436),(3437),(3439),(3440),(3441),(3442),(3444),(3445),(3446),(3447),(3448),(3450),(4101),(4102),(4103),(4104),(4105),(4106),(4107),(4108),(4109),(4110),(4111),(4112),(4113),(4114),(4115),(4116),(4117),(4118),(4119),(4120),(4121),(4122),(4123),(4124),(4125),(4126),(4127),(4128),(4129),(4130),(4131),(4132),(4133),(4134),(4135),(4136),(4137),(4138),(4139),(4141),(4142),(4143),(4144),(4145),(4146),(4147),(4148),(4149),(4150),(4551),(4552),(4553),(4554),(4555),(4556),(4557),(4558),(4559),(4560),(4561),(4562),(4563),(4564),(4565),(4566),(4567),(4568),(4569),(4570),(4571),(4572),(4573),(4574),(4575),(4576),(4577),(4578),(4579),(4580),(4581),(4582),(4583),(4584),(4585),(4586),(4587),(4588),(4589),(4590),(4591),(4592),(4593),(4594),(4595),(4596)) AS v(dc_no) ON v.dc_no = d.dc_no
WHERE d.flock_id = 'd07f7336-7e6f-4cdb-841d-059fea1643b2'::uuid;

SELECT round(sum(amount)::numeric,2) AS total_amount, round(sum(tds_amount)::numeric,2) AS total_tds
FROM public.he_dispatch d
JOIN public.parties p ON p.id = d.party_id
WHERE d.flock_id = 'd07f7336-7e6f-4cdb-841d-059fea1643b2'::uuid
  AND p.name = 'Hitech Hatch Fresh Private Limited';
